//! 🧪️ A real shared actor remains in the authentic caller slot when the native physical recipient refuses.
use semio_framework_value::*;
use semio_framework_value_native_owned::native_decoding::{OriginalConstructionRecipient,OriginalConstructionAuthority};
struct Work{fuel:u64}
impl semio_framework_value::OriginalWorkRecipient for Work{type Context<'turn,'source>=() where 'source:'turn;fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn source_turn<'turn,'source>(&self,_:&())->Option<semio_framework_value::OriginalSourceTurnIdentity>where 'source:'turn{None}fn admits<'reply,'turn,'source>(&mut self,_:&mut (),quote:semio_framework_value::OriginalWorkQuote<'reply>,observed:u64,additional:u64)->semio_framework_value::OriginalWorkQuoteComplete<'reply>where 'source:'turn{quote.complete(Ok(observed.checked_add(additional).is_some_and(|n|n<=self.fuel)))}fn settle_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:semio_framework_value::OriginalWorkPartialCheck<'reply>)->semio_framework_value::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}fn recover_partial<'reply,'turn,'source>(&mut self,context:&mut (),check:semio_framework_value::OriginalWorkPartialCheck<'reply>)->semio_framework_value::OriginalWorkPartialCheckComplete<'reply>where 'source:'turn{check.complete(self.validate_context(context))}}
struct Physical{submitted:RetainedCloneProgress,grant:RetainedCloneGrant}
impl OriginalConstructionRecipient for Physical{type Context<'turn,'source>=() where 'source:'turn;fn source_turn<'turn,'source>(&self,_:&())->Option<semio_framework_value::OriginalSourceTurnIdentity>where 'source:'turn{None}fn validate_context<'turn,'source>(&self,_:&())->Result<(),ValueError>where 'source:'turn{Ok(())}fn grant<'a,'turn,'source>(&mut self,_:&mut (),quote:semio_framework_value_control_contract::OriginalConstructionGrant<'a>)->semio_framework_value_control_contract::OriginalConstructionGrantComplete<'a>where 'source:'turn{quote.complete(Ok(self.grant))}fn accept<'a,'turn,'source>(&mut self,_:&mut (),receipt:semio_framework_value_control_contract::OriginalConstructionAccept<'a>)->semio_framework_value_control_contract::OriginalConstructionAcceptComplete<'a>where 'source:'turn{let g=receipt.grant();let p=receipt.progress();assert!(p.fits(g)&&p.fits(self.grant));let result=self.submitted.checked_add(p).and_then(|sum|{self.submitted=sum;Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"actual native actor receipt refusal"))});receipt.complete(result)}fn submitted<'turn,'source>(&self,_:&())->RetainedCloneProgress where 'source:'turn{self.submitted}}
#[test]fn native_shared_actor_stays_owned_before_receipt_refusal_and_is_paid_closed(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../../📦️paged/🎮️append/🎟️work/📐️.json")).unwrap();let s=&f["stock"];let mut left=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let g=|left:RetainedCloneGrant|RetainedCloneGrant{maximum_items:left.maximum_items.min(1),maximum_copy_bytes:left.maximum_copy_bytes.min(4096),maximum_capacity_bytes:left.maximum_capacity_bytes.min(65536),maximum_release_bytes:left.maximum_release_bytes.min(65536),maximum_depth:left.maximum_depth};let debit=|left:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,w:u64|{assert!(p.fits(*left));left.maximum_items-=p.copied_items;left.maximum_copy_bytes-=p.copied_bytes;left.maximum_capacity_bytes-=p.retained_capacity_bytes;left.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(w).unwrap();};let mut input=Some(f["text"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut output=None;let mut callback=|_|true;let mut native=semio_framework_value::NativeDecodeControl::new(left.maximum_capacity_bytes,&mut callback);let mut physical=OriginalConstructionAuthority::new(Physical{submitted:Default::default(),grant:g(left)});let mut work=semio_framework_value_native_owned::native_decoding::OriginalWorkAuthority::new(Work{fuel:fuel.min(1)});
 let turn=physical.with_loan(&mut (),|loan|work.with_loan(&mut (),|work_loan|native.with_work_recipient(work_loan,|native|native.with_construction_recipient(loan,|native|Ok::<_,ValueError>(SharedUtf8::receive_original(&mut input,&mut output,native,g(left)))))).unwrap()).unwrap().unwrap();assert_eq!(turn.work,1);assert_eq!(native.actual_work(),1);let error=turn.result.unwrap_err();assert!(error.primary.is_none());assert!(error.quote_refusal.is_some());assert!(input.is_none());let output=output.take().unwrap();assert_eq!(output.as_ptr(),pointer);assert_eq!(serde_json::to_value(&output).unwrap(),f["text"]);debit(&mut left,&mut fuel,error.retained_progress(),turn.work);
 let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new((output,error)).ok().unwrap();debit(&mut left,&mut fuel,RetainedCloneProgress{copied_items:1,..Default::default()},1);for _ in 0..100000{if owner.terminal_is_empty(){break}let mut actual=None;let mut effect=semio_framework_value_control_contract::RetainedAllocationEffect::new(g(left),fuel,&mut actual);let result=owner.step(&mut effect);let w=owner.last_turn_work();let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());debit(&mut left,&mut fuel,p,w);result.unwrap();}assert!(owner.terminal_is_empty());
}
